contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public {
        uint beforeC = address(c).balance;

        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;

        assert(
            (reverted && afterC == beforeC) ||
            (!reverted && afterC == beforeC - amount)
        );
    }

    receive() external payable {}
}

