pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount) internal {
        uint beforeC = address(c).balance;
        bool reverted;
        try c.sendTo(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        assertTrue((reverted && afterC == beforeC) ||
            (!reverted && afterC == beforeC - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
